#!/bin/sh
# Print docs/decisions/index.md, built from each record's heading and Status line.
set -eu

dir="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)/docs/decisions"

cat <<'EOF'
# Decision records

<!-- Generated by `make docs` from the records in this directory. Do not edit. -->

Each record explains one architectural decision. Accepted records are never edited except for the Status line. See [0001](0001-record-architecture-decisions.md).

A record has one of these statuses:

- `Accepted`: the decision is in force.
- `Superseded by NNNN`: a newer record replaced the decision. NNNN is that record's number.

| Number | Title | Status |
|---|---|---|
EOF

for path in "$dir"/[0-9][0-9][0-9][0-9]-*.md; do
	[ -e "$path" ] || continue
	name=$(basename "$path")
	number=$(printf '%s' "$name" | cut -c1-4)
	title=$(sed -n '1s/^# [0-9][0-9][0-9][0-9]\. //p' "$path")
	status=$(sed -n 's/^Status: //p' "$path" | head -n 1)
	if [ -z "$title" ] || [ -z "$status" ]; then
		echo "$name: needs a '# NNNN. Title' first line and a 'Status:' line" >&2
		exit 1
	fi
	printf '| %s | [%s](%s) | %s |\n' "$number" "$title" "$name" "$status"
done
